import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.D7Pdja0E.js";const u=JSON.parse('{"title":"외부 링크 관리","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/external-links.md","filePath":"04-org-admin-guide/external-links.md","lastUpdated":1776993543000}'),i={name:"04-org-admin-guide/external-links.md"};function l(d,t,n,s,h,S){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="외부-링크-관리" tabindex="-1">외부 링크 관리 <a class="header-anchor" href="#외부-링크-관리" aria-label="Permalink to &quot;외부 링크 관리&quot;">​</a></h1><p>사이드바에 외부 웹 서비스 링크를 추가하여 사용자가 빠르게 외부 서비스에 접근할 수 있도록 합니다. SSO 연동과 함께 사용하면 로그인 없이 외부 서비스로 이동할 수 있습니다.</p><h2 id="외부-링크-추가" tabindex="-1">외부 링크 추가 <a class="header-anchor" href="#외부-링크-추가" aria-label="Permalink to &quot;외부 링크 추가&quot;">​</a></h2><ol><li>관리자 메뉴 &gt; <strong>외부 링크 관리</strong>로 이동합니다.</li><li><strong>&quot;+ 링크 추가&quot;</strong> 버튼을 클릭합니다.</li><li>다음 정보를 입력합니다:</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>이름</td><td>사이드바에 표시되는 링크 이름</td></tr><tr><td>URL</td><td>외부 서비스 URL</td></tr><tr><td>열기 방식</td><td>iframe(앱 내 표시) 또는 새 탭</td></tr><tr><td>SSO 연동</td><td>SSO 설정이 있으면 자동 로그인 연동 가능</td></tr></tbody></table><h2 id="열기-방식" tabindex="-1">열기 방식 <a class="header-anchor" href="#열기-방식" aria-label="Permalink to &quot;열기 방식&quot;">​</a></h2><ul><li><strong>iframe</strong>: Workhub 앱 내에서 외부 서비스를 표시합니다. 일부 사이트는 iframe을 차단할 수 있으며, 이 경우 자동으로 감지하여 안내합니다.</li><li><strong>새 탭</strong>: 새 브라우저 탭에서 외부 서비스를 엽니다.</li></ul><h2 id="순서-변경" tabindex="-1">순서 변경 <a class="header-anchor" href="#순서-변경" aria-label="Permalink to &quot;순서 변경&quot;">​</a></h2><p>링크 목록에서 드래그하여 표시 순서를 변경할 수 있습니다. 변경된 순서는 사이드바에 즉시 반영됩니다.</p><h2 id="sso-연동" tabindex="-1">SSO 연동 <a class="header-anchor" href="#sso-연동" aria-label="Permalink to &quot;SSO 연동&quot;">​</a></h2><p>외부 링크에 SSO 설정을 연결하면, 사용자가 링크를 클릭할 때 SSO를 통해 자동으로 로그인된 상태로 외부 서비스에 접근합니다.</p><ol><li>외부 링크 편집에서 <strong>SSO 연동</strong> 옵션을 선택합니다.</li><li>등록된 SSO 설정 중 연동할 서비스를 선택합니다.</li><li>사용자가 링크를 클릭하면 SSO 인증 후 외부 서비스로 이동합니다.</li></ol>',12)])])}const _=a(i,[["render",l]]);export{u as __pageData,_ as default};
